18→export function registerVerifyTool(server: McpServer): void {
19→	server.tool(
20→		"verify",
21→		"Cross-verify by running the same prompt across multiple models of one agent. Compares results for consistency.",
22→		schema,
23→		async (params) => {
24→			const agent = getAgent(params.agent);
25→			if (!agent) {
26→				return {
27→					content: [
28→						{
29→							type: "text" as const,
30→							text: `Agent '${params.agent}' is not available.`,
31→						},
32→					],
33→				};
34→			}
35→
36→			const models = params.models ?? agent.getModels();
37→			if (models.length === 0) {
38→				return {
39→					content: [
40→						{
41→							type: "text" as const,
42→							text: `No models available for agent '${params.agent}'.`,
43→						},
44→					],
45→				};
46→			}
47→
48→			const result = await crossVerify(agent, {
49→				prompt: params.prompt,
50→				models,
51→				context: params.context,
52→				timeout: params.timeout,
53→			});
54→
55→			const sessionId = getOrCreateActiveSession();
56→			for (const response of result.responses) {
57→				addEntry(sessionId, {
58→					tool: "verify",
59→					agent: response.agent,
60→					model: response.model,
61→					prompt: params.prompt,
62→					response: response.content,
63→					durationMs: response.durationMs,
64→					exitCode: response.exitCode,
65→					error: response.error,
66→				});
67→			}
68→
69→			return {
70→				content: [{ type: "text" as const, text: result.formatted }],
71→			};
72→		},
73→	);
74→}
