 1→import type { AgentResponse, IAgent } from "../agents/types.js";
 2→import { formatVerificationResult } from "./aggregator.js";
 3→import { logger } from "../utils/logger.js";
 4→
 5→export interface VerificationOptions {
 6→	prompt: string;
 7→	models: string[];
 8→	timeout?: number;
 9→	cwd?: string;
10→	context?: string;
11→}
12→
13→export interface VerificationResult {
14→	agent: string;
15→	responses: AgentResponse[];
16→	formatted: string;
17→	totalDurationMs: number;
18→}
19→
20→export async function crossVerify(
21→	agent: IAgent,
22→	options: VerificationOptions,
23→): Promise<VerificationResult> {
24→	const startTime = Date.now();
25→	const { prompt, models, timeout, cwd, context } = options;
26→
27→	logger.info(`Cross-verifying ${agent.id} with ${models.length} models: ${models.join(", ")}`);
28→
29→	const results = await Promise.allSettled(
30→		models.map((model) =>
31→			agent.execute({
32→				prompt,
33→				model,
34→				timeout,
35→				cwd,
36→				context,
37→			}),
38→		),
39→	);
40→
41→	const responses: AgentResponse[] = [];
42→	for (const result of results) {
43→		if (result.status === "fulfilled") {
44→			responses.push(result.value);
45→		}
46→	}
47→
48→	const formatted = formatVerificationResult(agent.id, responses);
49→
50→	return {
51→		agent: agent.id,
52→		responses,
53→		formatted,
54→		totalDurationMs: Date.now() - startTime,
55→	};
56→}
