 1→import type { AgentResponse, ExecutionOptions, IAgent } from "../agents/types.js";
 2→import { logger } from "../utils/logger.js";
 3→
 4→export interface ParallelResult {
 5→	responses: AgentResponse[];
 6→	errors: Array<{ agent: string; error: string }>;
 7→	totalDurationMs: number;
 8→}
 9→
10→export async function executeParallel(
11→	agents: IAgent[],
12→	options: ExecutionOptions,
13→): Promise<ParallelResult> {
14→	const startTime = Date.now();
15→
16→	logger.info(`Executing ${agents.length} agents in parallel`);
17→
18→	const results = await Promise.allSettled(agents.map((agent) => agent.execute(options)));
19→
20→	const responses: AgentResponse[] = [];
21→	const errors: Array<{ agent: string; error: string }> = [];
22→
23→	for (let i = 0; i < results.length; i++) {
24→		const result = results[i];
25→		const agent = agents[i];
26→
27→		if (result.status === "fulfilled") {
28→			responses.push(result.value);
29→			if (result.value.error) {
30→				errors.push({ agent: agent.id, error: result.value.error });
31→			}
32→		} else {
33→			errors.push({
34→				agent: agent.id,
35→				error: result.reason instanceof Error ? result.reason.message : String(result.reason),
36→			});
37→		}
38→	}
39→
40→	return {
41→		responses,
42→		errors,
43→		totalDurationMs: Date.now() - startTime,
44→	};
45→}
