  1→import type { AgentConfig, AgentId, AgentResponse, ExecutionOptions, HealthStatus, IAgent } from "./types.js";
  2→import { spawnAgent, type SpawnOptions } from "../orchestrator/executor.js";
  3→import { isCliAvailable } from "../utils/detect.js";
  4→import { logger } from "../utils/logger.js";
  5→
  6→export abstract class BaseAgent implements IAgent {
  7→	abstract readonly id: AgentId;
  8→	abstract readonly displayName: string;
  9→	abstract readonly cliCommand: string;
 10→
 11→	protected config: AgentConfig;
 12→
 13→	constructor(config: AgentConfig) {
 14→		this.config = config;
 15→	}
 16→
 17→	async isAvailable(): Promise<boolean> {
 18→		return isCliAvailable(this.cliCommand);
 19→	}
 20→
 21→	getModels(): string[] {
 22→		return this.config.models;
 23→	}
 24→
 25→	getDefaultModel(): string {
 26→		return this.config.default;
 27→	}
 28→
 29→	async execute(options: ExecutionOptions): Promise<AgentResponse> {
 30→		const model = options.model ?? this.getDefaultModel();
 31→		const spawnOptions = this.buildSpawnOptions(options, model);
 32→
 33→		logger.info(`Executing ${this.displayName} with model ${model}`);
 34→
 35→		const result = await spawnAgent(spawnOptions);
 36→
 37→		if (result.timedOut) {
 38→			return {
 39→				agent: this.id,
 40→				model,
 41→				content: "",
 42→				durationMs: result.durationMs,
 43→				exitCode: 124,
 44→				error: `Timed out after ${options.timeout ?? 120000}ms`,
 45→			};
 46→		}
 47→
 48→		const content = this.parseOutput(result.stdout, result.stderr);
 49→
 50→		return {
 51→			agent: this.id,
 52→			model,
 53→			content,
 54→			durationMs: result.durationMs,
 55→			exitCode: result.exitCode,
 56→			error: result.exitCode !== 0 ? result.stderr || `Exit code: ${result.exitCode}` : undefined,
 57→		};
 58→	}
 59→
 60→	async healthCheck(): Promise<HealthStatus> {
 61→		const startTime = Date.now();
 62→
 63→		const available = await this.isAvailable();
 64→		if (!available) {
 65→			return {
 66→				agent: this.id,
 67→				available: false,
 68→				authenticated: false,
 69→				error: `CLI '${this.cliCommand}' not found`,
 70→			};
 71→		}
 72→
 73→		try {
 74→			const response = await this.execute({
 75→				prompt: "Reply with exactly: OK",
 76→				timeout: 30_000,
 77→			});
 78→
 79→			return {
 80→				agent: this.id,
 81→				available: true,
 82→				authenticated: response.exitCode === 0,
 83→				latencyMs: Date.now() - startTime,
 84→				error: response.error,
 85→			};
 86→		} catch (err) {
 87→			return {
 88→				agent: this.id,
 89→				available: true,
 90→				authenticated: false,
 91→				latencyMs: Date.now() - startTime,
 92→				error: err instanceof Error ? err.message : String(err),
 93→			};
 94→		}
 95→	}
 96→
 97→	protected abstract buildSpawnOptions(options: ExecutionOptions, model: string): SpawnOptions;
 98→
 99→	protected parseOutput(stdout: string, _stderr: string): string {
100→		return stdout.trim();
101→	}
102→}
