18→export function registerAskAllTool(server: McpServer): void {
19→	server.tool(
20→		"ask_all",
21→		"Ask multiple agents the same question in parallel. Use for explicit multi-agent comparison.",
22→		schema,
23→		async (params) => {
24→			let agents;
25→			if (params.agents && params.agents.length > 0) {
26→				agents = params.agents
27→					.map((id) => getAgent(id))
28→					.filter((a): a is NonNullable<typeof a> => a != null);
29→			} else {
30→				agents = await getAvailableAgents();
31→			}
32→
33→			if (agents.length === 0) {
34→				return {
35→					content: [{ type: "text" as const, text: "No agents available." }],
36→				};
37→			}
38→
39→			const result = await executeParallel(agents, {
40→				prompt: params.prompt,
41→				context: params.context,
42→				timeout: params.timeout,
43→			});
44→
45→			const sessionId = getOrCreateActiveSession();
46→			for (const response of result.responses) {
47→				addEntry(sessionId, {
48→					tool: "ask_all",
49→					agent: response.agent,
50→					model: response.model,
51→					prompt: params.prompt,
52→					response: response.content,
53→					durationMs: response.durationMs,
54→					exitCode: response.exitCode,
55→					error: response.error,
56→				});
57→			}
58→
59→			return {
60→				content: [{ type: "text" as const, text: formatParallelResult(result) }],
61→			};
62→		},
63→	);
