 10→const schema = {
 11→	task: z.string().describe("The task to delegate"),
 12→	agent: z
 13→		.enum(["claude", "codex", "gemini", "copilot"])
 14→		.optional()
 15→		.describe("Preferred agent (auto-selected if omitted)"),
 16→	allowParallel: z
 17→		.boolean()
 18→		.default(true)
 19→		.describe("Allow splitting large tasks across multiple agents"),
 20→	context: z.string().optional().describe("Additional context"),
 21→	timeout: z.number().optional().describe("Timeout in ms"),
 22→};
 23→
 24→export function registerDelegateTaskTool(server: McpServer): void {
 25→	server.tool(
 26→		"delegate_task",
 27→		"Delegate a task to agent(s). Automatically analyzes complexity and routes to single or parallel execution.",
 28→		schema,
 29→		async (params) => {
 30→			const complexity = analyzeComplexity(params.task);
 31→			const sessionId = getOrCreateActiveSession();
 32→
 33→			// Simple or complex: single agent
 34→			if (complexity.level !== "large" || !params.allowParallel) {
 35→				let agent;
 36→				if (params.agent) {
 37→					agent = getAgent(params.agent);
 38→				} else {
 39→					const available = await getAvailableAgents();
 40→					agent = available[0];
 41→				}
 42→
 43→				if (!agent) {
 44→					return {
 45→						content: [{ type: "text" as const, text: "No agents available for delegation." }],
 46→					};
 47→				}
 48→
 49→				const extendedTimeout =
 50→					complexity.level === "complex" ? (params.timeout ?? 120_000) * 2 : params.timeout;
 51→
 52→				const response = await agent.execute({
 53→					prompt: params.task,
 54→					context: params.context,
 55→					timeout: extendedTimeout,
 56→				});
 57→
 58→				addEntry(sessionId, {
 59→					tool: "delegate_task",
 60→					agent: response.agent,
 61→					model: response.model,
 62→					prompt: params.task,
 63→					response: response.content,
 64→					durationMs: response.durationMs,
 65→					exitCode: response.exitCode,
 66→					error: response.error,
 67→				});
 68→
 69→				const header = `**Complexity**: ${complexity.level} (score: ${complexity.score})\n**Reasons**: ${complexity.reasons.join(", ")}\n\n`;
 70→				return {
 71→					content: [
 72→						{ type: "text" as const, text: header + formatSingleResponse(response) },
 73→					],
 74→				};
 75→			}
 76→
 77→			// Large task: parallel delegation
 78→			const agents = await getAvailableAgents();
 79→			if (agents.length === 0) {
 80→				return {
 81→					content: [{ type: "text" as const, text: "No agents available for delegation." }],
 82→				};
 83→			}
 84→
 85→			const result = await executeParallel(agents, {
 86→				prompt: params.task,
 87→				context: params.context,
 88→				timeout: params.timeout ? params.timeout * 2 : 240_000,
