 1→import type { AgentId, IAgent } from "./types.js";
 2→import { ClaudeAgent } from "./claude-agent.js";
 3→import { CodexAgent } from "./codex-agent.js";
 4→import { GeminiAgent } from "./gemini-agent.js";
 5→import { CopilotAgent } from "./copilot-agent.js";
 6→import { loadModelsConfig } from "../config/loader.js";
 7→import { detectCaller } from "../utils/detect.js";
 8→import { logger } from "../utils/logger.js";
 9→
10→let registry: Map<AgentId, IAgent> | null = null;
11→
12→export function getAgentRegistry(): Map<AgentId, IAgent> {
13→	if (registry) return registry;
14→
15→	const config = loadModelsConfig();
16→	const caller = detectCaller();
17→
18→	if (caller) {
19→		logger.info(`Detected caller: ${caller} — excluding from available agents`);
20→	}
21→
22→	registry = new Map<AgentId, IAgent>();
23→
24→	const agents = config.agents;
25→	const agentFactories: Record<AgentId, () => IAgent> = {
26→		claude: () => new ClaudeAgent(agents.claude!),
27→		codex: () => new CodexAgent(agents.codex!),
28→		gemini: () => new GeminiAgent(agents.gemini!),
29→		copilot: () => new CopilotAgent(agents.copilot!),
30→	};
31→
32→	for (const [id, factory] of Object.entries(agentFactories)) {
33→		if (id === caller) {
34→			logger.info(`Skipping ${id} (caller) to prevent recursive invocation`);
35→			continue;
36→		}
37→		registry.set(id as AgentId, factory());
38→	}
39→
40→	return registry;
41→}
42→
43→export function getAgent(id: AgentId): IAgent | undefined {
44→	return getAgentRegistry().get(id);
45→}
46→
47→export async function getAvailableAgents(): Promise<IAgent[]> {
48→	const agents = Array.from(getAgentRegistry().values());
49→	const checks = await Promise.all(
50→		agents.map(async (agent) => ({
51→			agent,
52→			available: await agent.isAvailable(),
53→		})),
54→	);
55→	return checks.filter((c) => c.available).map((c) => c.agent);
56→}
57→
58→export function getAllRegisteredAgents(): IAgent[] {
59→	return Array.from(getAgentRegistry().values());
60→}
61→
62→export function resetRegistry(): void {
63→	registry = null;
64→}
